/**
 * The client half of ranking — and the reason the Map can work with no signal.
 * `Open Questions §4.4`.
 *
 * ⭐ The server ships each node's DOI *components* already computed (the
 * expensive, divergent half: personalised PageRank, corroboration, staleness)
 * plus the weight vector. All that is left here is a weighted sum and a
 * distance penalty — ten lines that are provably the same ten lines as
 * `portable.rank_portable`.
 *
 * ⚠️ This file has a conformance test (`frontier.test.ts`) that loads a fixture
 * generated by the backend and asserts identical output. **If you change the
 * arithmetic here, that test fails** — which is the entire point. The previous
 * arrangement had the client inventing its own ranking, and the Map quietly
 * ranked by a different definition of "interesting" than the Bench.
 *
 * ⭐ What this buys: re-ranking needs no server. A student at a bench with no
 * wifi can change focus, re-sort the frontier, and ask "what next" against a
 * cached payload. That is the moment the whole product is for, and it used to
 * require a round trip.
 */

export interface PortableNode {
  key: string;
  attributes: {
    type: string; kind: string | null;
    support: string; strength: string;
    corroboration: number; singleMethod: boolean;
    doi: Record<string, number>;
    hops: number;
    label?: string;
  };
}
export interface Portable {
  options: { type: string; multi: boolean; allowSelfLoops: boolean };
  attributes: {
    weights: Record<string, number>;
    distancePenalty: number;
    seeds: string[];
    maxHops: number;
    nodeCount: number;
  };
  nodes: PortableNode[];
  edges: Array<{ key: string; source: string; target: string; attributes: { relation: string } }>;
}

export interface Ranked { id: string; score: number; node: PortableNode }

/** Round to 5dp the same way Python's `round()` presents these. */
const r5 = (n: number) => Math.round((n + Number.EPSILON) * 1e5) / 1e5;

/**
 * ⚠️ Every line here has a twin in `portable.rank_portable`. Keep them
 * identical or the conformance fixture will say so.
 */
export function rankPortable(p: Portable, hops?: Map<string, number>): Ranked[] {
  const w = p.attributes.weights;
  const dp = p.attributes.distancePenalty;
  const out: Ranked[] = p.nodes.map((n) => {
    let api = 0;
    for (const k of Object.keys(n.attributes.doi)) api += (w[k] ?? 0) * n.attributes.doi[k];
    const d = hops?.get(n.key) ?? n.attributes.hops;
    return { id: n.key, score: r5(api - dp * d), node: n };
  });
  // ⚠️ ties break on id, ascending — matching Python's `(-score, id)`. Without
  // this the two runtimes agree on scores and disagree on order, which is the
  // hardest kind of drift to notice.
  out.sort((a, b) => (b.score - a.score) || (a.id < b.id ? -1 : a.id > b.id ? 1 : 0));
  return out;
}

/**
 * Breadth-first distance from a new focus — so the client can RE-SEED without
 * the server. This is what makes the payload a graph rather than a ranking.
 */
export function hopsFrom(p: Portable, seeds: string[]): Map<string, number> {
  const adj = new Map<string, string[]>();
  const push = (a: string, b: string) => {
    const l = adj.get(a); if (l) l.push(b); else adj.set(a, [b]);
  };
  for (const e of p.edges) { push(e.source, e.target); push(e.target, e.source); }

  const dist = new Map<string, number>();
  let frontier = seeds.filter((s) => adj.has(s) || p.nodes.some((n) => n.key === s));
  for (const s of frontier) dist.set(s, 0);
  let d = 0;
  while (frontier.length && d < p.attributes.maxHops) {
    d += 1;
    const next: string[] = [];
    for (const id of frontier) {
      for (const nb of adj.get(id) ?? []) {
        if (!dist.has(nb)) { dist.set(nb, d); next.push(nb); }
      }
    }
    frontier = next;
  }
  // ⚠️ unreached nodes get maxHops + 1, exactly as the server does — not
  // Infinity, which would sort them into a different place entirely.
  for (const n of p.nodes) if (!dist.has(n.key)) dist.set(n.key, p.attributes.maxHops + 1);
  return dist;
}

/**
 * ⭐ The frontier, offline: what can you do next, ranked, with no server.
 *
 * "Reachable" is the Knowledge Space Theory outer fringe — a gap whose
 * prerequisites you already hold. That is the one question a student at a
 * bench actually asks, and it is pure graph work: no model, no tokens, no
 * network.
 */
export function offlineFrontier(p: Portable, focus: string[] = [], limit = 5): Ranked[] {
  const hops = focus.length ? hopsFrom(p, focus) : undefined;
  return rankPortable(p, hops)
    .filter((r) => {
      const t = r.node.attributes.type;
      // gaps and questions are actionable; established concepts are not
      return (t === "Question" || t === "Concept") &&
             r.node.attributes.strength !== "established";
    })
    .slice(0, limit);
}

/** Cache key — the payload is safe to keep because the weights ride with it. */
export const PORTABLE_CACHE = "mg_portable_v1";

export function cachePortable(p: Portable) {
  try { localStorage.setItem(PORTABLE_CACHE, JSON.stringify(p)); } catch { /* quota */ }
}
export function readCachedPortable(): Portable | null {
  try {
    const raw = localStorage.getItem(PORTABLE_CACHE);
    return raw ? (JSON.parse(raw) as Portable) : null;
  } catch { return null; }
}
